export const getAgendamentosCalendarioUrl = (id: string,) => {




  return `/api/v1/agendamentos/${id}/calendario.ics`
}

export const agendamentosCalendario = async (id: string, options?: Parameters<typeof chamarApi>[1]): Promise<string> => {

  return chamarApi<string>(getAgendamentosCalendarioUrl(id),
  {
    ...options,
    method: 'GET'


  }
);}





export const getAgendamentosCalendarioQueryKey = (id: string,) => {
    return [
    `/api/v1/agendamentos/${id}/calendario.ics`
    ] as const;
    }


